arguments.command:
python3 - << 'PY'
from pathlib import Path
p = Path('/workspace/lib/widgets/hero_feedback_surface.dart')
s = p.read_text()
start = s.find('class _SeekBottomHud extends StatelessWidget')
end = s.find('\n}\n\nclass _TapRingPainter', start)
print(start, end)
if start != -1:
    new_block = '''class _SeekBottomHud extends StatelessWidget {
  const _SeekBottomHud({
    required this.targetMs,
    required this.durationMs,
    required this.palette,
    required this.typography,
  });

  final int targetMs;
  final int durationMs;
  final AppPalette palette;
  final AppTypography typography;

  @override
  Widget build(BuildContext context) {
    final targetText = formatClock(targetMs);
    final durationText = durationMs > 0 ? formatClock(durationMs) : '--:--';
    final fraction = durationMs > 0 ? (targetMs / durationMs).clamp(0.0, 1.0) : 0.0;
    return SizedBox(
      height: 34.0,
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: palette.background,
          border: Border(top: BorderSide(color: palette.divider, width: 1)),
        ),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 12.0, vertical: 6.0),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'Target $targetText / $durationText',
                style: TextStyle(
                  color: palette.fgPrimary,
                  fontFamily: typography.monoFamily,
                  fontSize: typography.hintSize,
                  height: 1.2,
                ),
              ),
              const SizedBox(height: 4),
              SizedBox(
                height: 6,
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(3.0),
                  child: LinearProgressIndicator(
                    value: fraction,
                    backgroundColor: palette.divider,
                    valueColor: AlwaysStoppedAnimation<Color>(palette.progress),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
'''
s2 = s[:start] + new_block + s[end+3:]
p.write_text(s2)
print('Replaced block')
